<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Item; use App\Models\Report; use App\Models\User; use Illuminate\Http\Request;
class SafetyController extends Controller { public function reportItem(Request $r,Item $item){return $this->report($r,$item);} public function reportUser(Request $r,User $user){abort_if($user->id===$r->user()->id,422);return $this->report($r,$user);} public function block(Request $r,User $user){abort_if($user->id===$r->user()->id,422);$r->user()->blockedUsers()->syncWithoutDetaching([$user->id]);return $this->ok(null,'User blocked.');} private function report(Request $r,$target){$data=$r->validate(['reason'=>'required|in:fake,spam,inappropriate,suspicious,fraud','details'=>'nullable|string|max:2000']);$report=$target->reports()->firstOrCreate(['reporter_id'=>$r->user()->id],$data);return $this->ok($report,'Report submitted.',201);} private function ok($data,string $message,int $status=200){return response()->json(['success'=>true,'message'=>$message,'data'=>$data],$status);} }
